      "endpoint": "https://mcp.agent.eth/",
      "version": "2025-06-18"
    },
    {
      "name": "OASF",
      "endpoint": "ipfs://{cid}",
      "version": "0.8", // https://github.com/agntcy/oasf/tree/v0.8.0
      "skills": [], // OPTIONAL
      "domains": [] // OPTIONAL
    },
    {
      "name": "ENS",
      "endpoint": "vitalik.eth",
      "version": "v1"
    },
    {
      "name": "DID",
      "endpoint": "did:method:foobar",
      "version": "v1"
    },
    {
      "name": "email",
      "endpoint": "mail@myagent.com"
    }
  ],
  "x402Support": false,
  "active": true,
  "registrations": [
    {
      "agentId": 22,
      "agentRegistry": "{namespace}:{chainId}:{identityRegistry}" // e.g. eip155:1:0x742...
    }
  ],
  "supportedTrust": [
    "reputation",
    "crypto-economic",
    "tee-attestation"
  ]
}

Path: https://{endpoint-domain}/.well-known/agent-registration.json

Must contain "at least a `registrations` list (or the full agent registration file)".
Verified iff: reachable over HTTPS AND contains a `registrations` entry whose
`agentRegistry` and `agentId` match the on-chain agent.
Not needed when the endpoint-domain is the same domain serving the agentURI file.

Minimal body implied by the spec (shape taken from the registration file):
{
  "registrations": [
    { "agentId": 22, "agentRegistry": "eip155:1:0x742..." }
  ]
}
